@Composable private fun StateMessage(title:String,button:String?=null,onClick:()->Unit={}){Column(Modifier.fillMaxWidth().padding(32.dp)){Text(title,style=MaterialTheme.typography.bodyLarge);button?.let{Button(onClick){Text(it)}}}}
private fun displayDate(value:String?):String?=try{value?.let{LocalDate.parse(it).format(DateTimeFormatter.ofPattern("d MMMM yyyy"))}}catch(_:Exception){value}
private fun closingLabel(t:Tender):String{if(t.status!="OPEN")return "Closed";val date=t.closing_date?:return "Closing date unavailable";return try{when(LocalDate.parse(date)){LocalDate.now()->"Closes today";LocalDate.now().plusDays(1)->"Closes tomorrow";else->"Closes ${LocalDate.parse(date).format(DateTimeFormatter.ofPattern("d MMM"))}"}}catch(_:Exception){"Closes $date"}}
@Composable fun TenderCardView(t:Tender,saved:Boolean=false,onSave:(()->Unit)?=null,onClick:()->Unit){Card(Modifier.fillMaxWidth().padding(vertical=6.dp).clickable(onClick=onClick)){Column(Modifier.padding(16.dp)){Text(t.title,style=MaterialTheme.typography.titleMedium,fontWeight=FontWeight.SemiBold);Spacer(Modifier.height(5.dp));Text(t.organisation);Text(listOfNotNull(t.province,t.municipality).joinToString(" / "));Spacer(Modifier.height(10.dp));Text(closingLabel(t),style=MaterialTheme.typography.titleSmall,color=if(t.status=="OPEN")MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.error,fontWeight=FontWeight.Bold);t.category?.let{Text("Category: $it")};t.reference_number?.let{Text("Reference: $it")};if(t.status!="OPEN")Text(t.status,color=MaterialTheme.colorScheme.error,fontWeight=FontWeight.Bold);onSave?.let{TextButton(it){Text(if(saved)"Saved" else "Save")}}}}}
@Composable fun HomeDataScreen(state:DataState<HomeResponse>,onRetry:()->Unit,onTender:(String)->Unit,savedIds:Set<String> = emptySet(),onSave:(String)->Unit={},onViewAll:(String)->Unit={}){when(state){DataState.Loading->StateMessage("Loading current tenders…");DataState.Empty->StateMessage("No current tenders are available.","Retry",onRetry);is DataState.Error->StateMessage(state.message,"Retry",onRetry);is DataState.Success->LazyColumn(Modifier.fillMaxSize().padding(16.dp)){item{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("Latest tenders",style=MaterialTheme.typography.headlineMedium);TextButton({onViewAll("newest")}){Text("View All")}}};items(state.data.latest,key={"latest-${it.id}"}){TenderCardView(it,it.id in savedIds,{onSave(it.id)}){onTender(it.id)}};item{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("Closing soon",style=MaterialTheme.typography.headlineMedium,modifier=Modifier.padding(top=20.dp));TextButton({onViewAll("closing_soon")}){Text("View All")}}};items(state.data.closing_soon,key={"closing-${it.id}"}){TenderCardView(it,it.id in savedIds,{onSave(it.id)}){onTender(it.id)}};item{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("Recently added",style=MaterialTheme.typography.headlineMedium,modifier=Modifier.padding(top=20.dp));TextButton({onViewAll("newest")}){Text("View All")}}};items(state.data.recently_added,key={"recent-${it.id}"}){TenderCardView(it,it.id in savedIds,{onSave(it.id)}){onTender(it.id)}}}}}
