@Composable fun SearchDataScreen(state:DataState<SearchResults>,filters:TenderFilters,geography:GeographyOptions,onSearch:(String,TenderFilters,String)->Unit,onRetry:()->Unit,onLoadMore:()->Unit,onTender:(String)->Unit,savedIds:Set<String>,onSave:(String)->Unit,history:List<String>,onClearHistory:()->Unit,onRemoveHistory:(String)->Unit,onSaveSearch:(String,String,TenderFilters,String)->Unit){var query by remember{mutableStateOf("")};var sort by remember{mutableStateOf("relevance")};var showFilters by remember{mutableStateOf(false)};var showSave by remember{mutableStateOf(false)};Column(Modifier.fillMaxSize().padding(16.dp)){Text("Search tenders",style=MaterialTheme.typography.headlineMedium);OutlinedTextField(query,{query=it},label={Text("Keywords")},singleLine=true,modifier=Modifier.fillMaxWidth());Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){OutlinedButton({showFilters=true}){Text("Filters${filters.activeCount().takeIf{it>0}?.let{" ($it)"}?:""}")};TextButton({sort=when(sort){"relevance"->"newest";"newest"->"closing_soon";else->"relevance"}}){Text("Sort: ${sort.replace('_',' ')}")}};Row{Button({onSearch(query,filters,sort)},Modifier.weight(1f)){Text("Search")};TextButton({showSave=true}){Text("Save Search")}};if(history.isNotEmpty()){Text("Recent searches",style=MaterialTheme.typography.labelLarge);history.take(3).forEach{value->Row{TextButton({query=value;onSearch(value,filters,sort)}){Text(value)};TextButton({onRemoveHistory(value)}){Text("Remove")}}};TextButton(onClearHistory){Text("Clear history")}};Box(Modifier.weight(1f)){when(state){DataState.Loading->StateMessage("Searching tenders…");DataState.Empty->StateMessage("No tenders match your search.");is DataState.Error->StateMessage(state.message,"Retry",onRetry);is DataState.Success->LazyColumn{items(state.data.items,key={it.id}){TenderCardView(it,it.id in savedIds,{onSave(it.id)}){onTender(it.id)}};if(state.data.page<state.data.totalPages)item{Button(onLoadMore,enabled=!state.data.loadingMore,modifier=Modifier.fillMaxWidth()){Text(if(state.data.loadingMore)"Loading…" else "Load more")}}}}}}
 if(showFilters)FilterSheet(filters,geography,onDismiss={showFilters=false}){showFilters=false;onSearch(query,it,sort)};if(showSave){var name by remember{mutableStateOf("")};AlertDialog(onDismissRequest={showSave=false},title={Text("Save search")},text={OutlinedTextField(name,{name=it},label={Text("Search name")})},confirmButton={TextButton({onSaveSearch(name,query,filters,sort);showSave=false},enabled=name.isNotBlank()){Text("Save")}},dismissButton={TextButton({showSave=false}){Text("Cancel")}})}}
