@Composable private fun FilterSheet(current:TenderFilters,geo:GeographyOptions,onDismiss:()->Unit,onApply:(TenderFilters)->Unit){var draft by remember(current){mutableStateOf(current)};val districts=geo.districts.filter{draft.provinceId==null||it.province_id==draft.provinceId};val municipalities=geo.municipalities.filter{(draft.provinceId==null||it.province_id==draft.provinceId)&&(draft.districtId==null||it.district_id==draft.districtId)};ModalBottomSheet(onDismissRequest=onDismiss){LazyColumn(Modifier.fillMaxWidth().padding(horizontal=20.dp),contentPadding=PaddingValues(bottom=32.dp)){item{Text("Search filters",style=MaterialTheme.typography.headlineSmall);Section("Location");DropdownField("Province",geo.provinces,draft.provinceId,{it.id},{it.name}){draft=draft.copy(provinceId=it,districtId=null,municipalityId=null)};DropdownField("District",districts,draft.districtId,{it.id},{it.name}){draft=draft.copy(districtId=it,municipalityId=null)};DropdownField("Municipality",municipalities,draft.municipalityId,{it.id},{it.name}){draft=draft.copy(municipalityId=it)};Section("Tender");FilterText("Category",draft.category){draft=draft.copy(category=it)};FilterText("Tender type",draft.tenderType){draft=draft.copy(tenderType=it)};FilterText("Organisation",draft.organisation){draft=draft.copy(organisation=it)};Section("Date");FilterText("Closing from (YYYY-MM-DD)",draft.closingFrom){draft=draft.copy(closingFrom=it)};FilterText("Closing to (YYYY-MM-DD)",draft.closingTo){draft=draft.copy(closingTo=it)};FilterText("Issue from (YYYY-MM-DD)",draft.issueFrom){draft=draft.copy(issueFrom=it)};FilterText("Issue to (YYYY-MM-DD)",draft.issueTo){draft=draft.copy(issueTo=it)};Section("Value");FilterText("Minimum value",draft.minValue){draft=draft.copy(minValue=it)};FilterText("Maximum value",draft.maxValue){draft=draft.copy(maxValue=it)};Section("Status");DropdownField("Status",listOf("OPEN","CLOSED","CANCELLED","UPCOMING"),draft.status.ifBlank{null},{it},{it}){draft=draft.copy(status=it?:"")};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){TextButton({draft=TenderFilters()}){Text("Clear")};Button({onApply(draft)}){Text("Apply filters")}}}}}}
