@Composable private fun <T> DropdownField(label:String,items:List<T>,selected:String?,id:(T)->String,name:(T)->String,onSelect:(String?)->Unit){var expanded by remember{mutableStateOf(false)};val display=items.firstOrNull{id(it)==selected}?.let(name)?:"Any";ExposedDropdownMenuBox(expanded,{expanded=it}){OutlinedTextField(display,{},readOnly=true,label={Text(label)},trailingIcon={ExposedDropdownMenuDefaults.TrailingIcon(expanded)},modifier=Modifier.menuAnchor().fillMaxWidth());ExposedDropdownMenu(expanded,{expanded=false}){DropdownMenuItem({Text("Any")},{onSelect(null);expanded=false});items.forEach{item->DropdownMenuItem({Text(name(item))},{onSelect(id(item));expanded=false})}}}}
@Composable private fun FilterText(label:String,value:String,onValue:(String)->Unit){OutlinedTextField(value,onValue,label={Text(label)},singleLine=true,modifier=Modifier.fillMaxWidth())}
@Composable fun TenderDetailScreen(state:DataState<TenderDetail>,onRetry:()->Unit,saved:Boolean=false,onSave:()->Unit={}){val uri=LocalUriHandler.current;when(state){DataState.Loading->StateMessage("Loading tender details…");DataState.Empty->StateMessage("Tender not found.");is DataState.Error->StateMessage(state.message,"Retry",onRetry);is DataState.Success->{val t=state.data;LazyColumn(Modifier.fillMaxSize().padding(20.dp)){item{Text(t.title,style=MaterialTheme.typography.headlineMedium);Text(t.organisation,style=MaterialTheme.typography.titleMedium);Button(onSave){Text(if(saved)"Saved" else "Save Tender")};Section("Overview");Field("Reference",t.reference_number);Section("Organisation");Field("Organisation",t.organisation);Field("Province",t.province);Field("Municipality",t.municipality);Field("District",t.district);Section("Timeline");Field("Issue date",displayDate(t.issue_date));Field("Closing",if(t.closing_date==null)"Closing date unavailable" else "${displayDate(t.closing_date)}${t.closing_time?.let{" at ${it.take(5)}"}?:""}");Section("Procurement");Field("Category",t.category);Field("Tender type",t.tender_type);Field("Status",t.status);Field("Estimated value",t.estimated_value?.let{"${t.currency} ${"%,.2f".format(it)}"});Field("Description",t.description);Section("Contact");Field("Contact",listOfNotNull(t.contact_name,t.contact_email,t.contact_phone).joinToString(" • ").ifBlank{null});Section("Source");Text("TenderHub SA is not the issuing authority.");Field("Publisher",t.source.name);Field("Source reference",t.source_reference);Field("Ingested",t.ingested_at);Button({uri.openUri(t.source_url)}){Text("View Original Source")};Section("Documents");if(t.documents.isEmpty())Text("No source documents supplied") else t.documents.forEach{TextButton({uri.openUri(it.source_url)}){Text("${it.name} — Open Document")}};Section("AI Analysis");Text("NOT IMPLEMENTED")}}}}}
@Composable private fun Section(value:String){Text(value,style=MaterialTheme.typography.titleLarge,modifier=Modifier.padding(top=24.dp,bottom=8.dp))}
